import{_ as o,a0 as p,w as s,s as d,ao as l,I as i,x as t,a1 as n,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"5 個基於Linux命令列的文件下載和網站瀏覽工具 | LCTT x X-CMD","titleTemplate":false,"description":"5 個基於Linux命令列的文件下載和網站瀏覽工具 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"5 個基於Linux命令列的文件下載和網站瀏覽工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"5 個基於Linux命令列的文件下載和網站瀏覽工具 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150407 5 Linux Command Line Based Tools for Downloading Files and Browsing Websites","title":"5 個基於Linux命令列的文件下載和網站瀏覽工具","tag":"201505","desc":""},"relativePath":"201505/20150407 5 Linux Command Line Based Tools for Downloading Files and Browsing Websites.md","filePath":"[post].md"}'),m={name:"201505/20150407 5 Linux Command Line Based Tools for Downloading Files and Browsing Websites.md"};function w(c,e,h,T,u,g){const r=p("Link");return s(),d("div",null,[e[16]||(e[16]=l(`<h1 id="_5-個基於linux命令列的文件下載和網站瀏覽工具" tabindex="-1">5 個基於Linux命令列的文件下載和網站瀏覽工具 <a class="header-anchor" href="#_5-個基於linux命令列的文件下載和網站瀏覽工具" aria-label="Permalink to “5 個基於Linux命令列的文件下載和網站瀏覽工具”">​</a></h1><p>Linux命令列是GNU/Linux中最神奇迷人的部分，它是非常強大的工具。命令列本身功能多樣，多種內建或者第三方的命令列應用使得Linux變得更加健壯和強大。Linux Shell支持多種不同類型的網絡應用，無論是BT下載軟件，專用下載器或者互聯網衝浪。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Command-Line-Internet-Tools.jpg" alt="命令列互聯網工具"></p><p><em>5個命令列互聯網工具</em></p><p>這裏我們介紹了5個很好的命令列互聯網工具，它們非常有用，也很容易上手。</p><h3 id="_1-rtorrent" tabindex="-1">1. rTorrent <a class="header-anchor" href="#_1-rtorrent" aria-label="Permalink to “1. rTorrent”">​</a></h3><p>rTorrent是基於文本，用C++編寫，追求高性能的Torrent客户端。支持大部分標準的Linux發行版，包括FreeBSD和Mac OS X。</p><h4 id="安裝rtorrent" tabindex="-1">安裝rTorrent <a class="header-anchor" href="#安裝rtorrent" aria-label="Permalink to “安裝rTorrent”">​</a></h4><pre><code># apt­-get install rtorrent    (基於 APT 的系統)
</code></pre><hr><pre><code># yum install rtorrent        (基於 YUM 的系統)
</code></pre><p>在終端中用下面的命令檢查rtorrent是否正確安裝</p><pre><code># rtorrent
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/rTorrent.jpeg" alt="命令列torrent下載器"></p><p><em>rTorrent命令列工具</em></p><h4 id="rtorrent的功能" tabindex="-1">rTorrent的功能 <a class="header-anchor" href="#rtorrent的功能" aria-label="Permalink to “rTorrent的功能”">​</a></h4><p>一些有用的快捷鍵和使用方法</p><ul><li>CTRL+ q – 退出rTorrent應用程序</li><li>CTRL+ s – 開始下載</li><li>CTRL+ d – 停止運行中的下載或者移除已完成的下載</li><li>CTRL+ k – 停止並關閉運行中的下載</li><li>CTRL+ r – 在上傳/下載種子之前進行Hash檢查</li><li>CTRL+ q – 執行兩次這個命令，rTorrent會直接退出而不發送“停止”信號</li><li>Left Arrow Key – 跳到上一屏幕</li><li>Right Arrow Key – 跳到下一屏幕</li></ul><h3 id="_2-wget" tabindex="-1">2. Wget <a class="header-anchor" href="#_2-wget" aria-label="Permalink to “2. Wget”">​</a></h3><p>Wget是GNU項目的一部分，名字由World Wide Web (WWW)衍生而來。Wget是用來遞歸下載、離線查看本地服務器HTML文件一個很好的工具，它可用於Windows， Mac，以及Linux等大部分平台。Wget能通過HTTP，HTTPS和FTP下載文件。另外，能鏡像整個網站，支持代理瀏覽以及暫停/回覆下載使得它更為有用。</p><h4 id="安裝wget" tabindex="-1">安裝Wget <a class="header-anchor" href="#安裝wget" aria-label="Permalink to “安裝Wget”">​</a></h4><p>由於是GNU項目的一部分，Wget捆綁在大部分標準Linux發行版中，不再需要獨立下載安裝。如果默認沒有安裝，你也可以使用apt或者yum安裝。</p><pre><code># apt­-get install wget        (基於 APT 的系統)
</code></pre><hr><pre><code># yum install wget        (基於 YUM 的系統)
</code></pre><h4 id="wget的一些基本用法" tabindex="-1">Wget的一些基本用法 <a class="header-anchor" href="#wget的一些基本用法" aria-label="Permalink to “Wget的一些基本用法”">​</a></h4><p>使用wget下載一個單獨的文件.</p><pre><code># wget http://www.website-name.com/file
</code></pre><p>遞歸下載整個網站.</p><pre><code># wget -r http://www.website-name.com
</code></pre><p>從一個網站下載指定類型的文件(例如 pdf 和 png).</p><pre><code># wget -r -A png,pdf http://www.website-name.com
</code></pre><p>Wget是一個很棒的工具，它允許在資源有限的機器上自定義或者過濾下載。這是鏡像一個網站(Yahoo.com)的wget下載截圖。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Wget.jpeg" alt="Wget 下載文件"></p><p><em>Wget 命令列文件下載</em></p>`,35)),i("p",null,[e[1]||(e[1]=t("要獲取更多wget下載的例子，可以閲讀我們的文章",-1)),n(r,{href:"https://linux.cn/article-4129-1.html"},{default:a(()=>[...e[0]||(e[0]=[t("Wget下載命令例子",-1)])]),_:1}),e[2]||(e[2]=t("。",-1))]),e[17]||(e[17]=l(`<h3 id="_3-curl" tabindex="-1">3. cURL <a class="header-anchor" href="#_3-curl" aria-label="Permalink to “3. cURL”">​</a></h3><p>cURL是在多種協議上傳輸數據的命令列工具。cURL是支持FTP, HTTP, FTPS, TFTP, TELNET, IMAP, POP3等協議的客户端應用。cURL是一個不同於wget 的簡單下載器，和其它的相比，它支持LDAP，POP3。cURL也很好的支持代理下載，暫停下載以及恢復下載。</p><h4 id="安裝curl" tabindex="-1">安裝cURL <a class="header-anchor" href="#安裝curl" aria-label="Permalink to “安裝cURL”">​</a></h4><p>在軟件倉庫或者已安裝軟件中，cURL在大部分發行版中默認是可用的。如果沒有安裝，運行apt或者yum從軟件倉庫中獲取需要的安裝包。</p><pre><code># apt­-get install curl        (基於 APT 的系統)
</code></pre><hr><pre><code># yum install curl        (基於 YUM 的系統)
</code></pre><p>cURL的基本使用方法</p><pre><code># curl www.tecmint.com
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Curl.jpeg" alt="Curl 下載"></p><p><em>Curl 下載</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Curl-2.jpeg" alt="Curl 下載數據"></p><p><em>Curl 下載</em></p><h3 id="_4-w3m" tabindex="-1">4. w3m <a class="header-anchor" href="#_4-w3m" aria-label="Permalink to “4. w3m”">​</a></h3><p>W3m是GPL協議下發布的基於文本的web瀏覽器。W3m支持表格，幀，顏色，SSL連接以及內聯圖像。W3m以快速瀏覽而出名。</p><h4 id="安裝w3m" tabindex="-1">安裝w3m <a class="header-anchor" href="#安裝w3m" aria-label="Permalink to “安裝w3m”">​</a></h4><p>W3m在大部分Linux發行版中也是默認可用的。如果不可用的話可以用apt或者yum獲取需要的安裝包。</p><pre><code># apt­-get install w3m        (基於 APT 的系統)
</code></pre><hr><pre><code># yum install w3m        (基於 YUM 的系統)
</code></pre><h4 id="w3m的基本使用方法" tabindex="-1">w3m的基本使用方法 <a class="header-anchor" href="#w3m的基本使用方法" aria-label="Permalink to “w3m的基本使用方法”">​</a></h4><pre><code># w3m www.tecmint.com
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/w3m.jpeg" alt="命令列瀏覽器"></p><p><em>基於文本的web瀏覽器w3m</em></p><h3 id="_5-elinks" tabindex="-1">5. Elinks <a class="header-anchor" href="#_5-elinks" aria-label="Permalink to “5. Elinks”">​</a></h3><p>Elinks是基於文本的免費瀏覽器，用於Unix及基於Unix的系統。Elinks支持 HTTP，HTTP Cookies以及支持瀏覽Perl和Ruby腳本（LCTT 譯註：應該是指 CGI）。也很好的支持選項卡瀏覽。最棒的是它支持鼠標、彩色以及支持一系列的協議，例如HTTP, FTP, SMB, Ipv4 和 Ipv6。</p><h4 id="安裝elinks" tabindex="-1">安裝Elinks <a class="header-anchor" href="#安裝elinks" aria-label="Permalink to “安裝Elinks”">​</a></h4><p>Elinks在大部分Linux發行版上是默認可用的。如果不是的話，可以通過apt或者yum安裝。</p><pre><code># apt­-get install elinks    (基於 APT 的系統)
</code></pre><hr><pre><code># yum install elinks        (基於 YUM 的系統)
</code></pre><p>Elinks的基本使用方法</p><pre><code># elinks www.tecmint.com
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Elinks.jpeg" alt="命令列互聯網瀏覽"></p><p><em>Elinks命令列瀏覽互聯網</em></p><p>就是這些了。有你們喜歡讀的有趣的文章，我會再次來到這裏。到那時盡請關注並保持和Tecmint的聯繫，別忘了在評論部分給我們你的寶貴的反饋。</p><hr>`,37)),i("p",null,[e[4]||(e[4]=t("via: ",-1)),n(r,{href:"http://www.tecmint.com/linux-command-line-tools-for-downloading-files/"},{default:a(()=>[...e[3]||(e[3]=[t("http://www.tecmint.com/linux-command-line-tools-for-downloading-files/",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=t("作者：",-1)),n(r,{href:"http://www.tecmint.com/author/avishek/"},{default:a(()=>[...e[5]||(e[5]=[t("Avishek Kumar",-1)])]),_:1}),e[9]||(e[9]=t(" 譯者：",-1)),n(r,{href:"https://github.com/ictlyh"},{default:a(()=>[...e[6]||(e[6]=[t("ictlyh",-1)])]),_:1}),e[10]||(e[10]=t(" 校對：",-1)),n(r,{href:"https://github.com/wxy"},{default:a(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[13]||(e[13]=t("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原創翻譯，",-1)),n(r,{href:"http://linux.cn/"},{default:a(()=>[...e[12]||(e[12]=[t("Linux中國",-1)])]),_:1}),e[15]||(e[15]=t(" 榮譽推出",-1))])])}const P=o(m,[["render",w]]);export{f as __pageData,P as default};
